const { performance } = require('node:perf_hooks')

function createTelemetryScheduler ({ now = () => performance.now(), budgetMs = 4,
  setTimer = setInterval, clearTimer = clearInterval,
  defer = setImmediate, cancelDefer = clearImmediate,
  onError = error => console.error('ControlPanel telemetry tick failed', error) } = {}) {
  const callbacks = new Set()
  let timer = null, continuation = null, batch = null, index = 0

  function drain () {
    continuation = null
    const start = now()
    while (batch && index < batch.length) {
      const callback = batch[index++]
      if (callbacks.has(callback)) {
        try { callback() } catch (error) { onError(error) }
      }
      if (batch && index < batch.length && now() - start >= budgetMs) {
        continuation = defer(drain)
        continuation?.unref?.()
        return
      }
    }
    batch = null
  }

  return {
    onTick (callback) {
      callbacks.add(callback)
      if (timer === null) {
        timer = setTimer(() => {
          // At most one sweep: slow consumers must not build a timer backlog.
          if (batch) return
          batch = [...callbacks]; index = 0
          drain()
        }, 1000 / 30)
        timer?.unref?.()
      }
      return () => {
        callbacks.delete(callback)
        if (callbacks.size) return
        clearTimer(timer); timer = null
        if (continuation !== null) cancelDefer(continuation)
        continuation = null; batch = null
      }
    },
    stats: () => ({ callbacks: callbacks.size, running: timer !== null, pending: batch !== null })
  }
}

module.exports = { createTelemetryScheduler }
